#include "re3_codec.h"
#include <stdio.h>
#include <string.h>
#define VW 800
#define VH 800
static re3c_u8 pix[VW*VH*3u];
static void put32(FILE*f,re3c_u32 v){re3c_u8 b[4];b[0]=(re3c_u8)v;b[1]=(re3c_u8)(v>>8);b[2]=(re3c_u8)(v>>16);b[3]=(re3c_u8)(v>>24);fwrite(b,1u,4u,f);}
static void put16(FILE*f,re3c_u16 v){re3c_u8 b[2];b[0]=(re3c_u8)v;b[1]=(re3c_u8)(v>>8);fwrite(b,1u,2u,f);}
static void clear_img(void){size_t i;for(i=0;i<sizeof(pix);i++)pix[i]=245u;}
static void dot(int x,int y,re3c_u8 r,re3c_u8 g,re3c_u8 b){size_t o;if(x<0||x>=VW||y<0||y>=VH)return;o=((size_t)y*VW+(size_t)x)*3u;pix[o]=b;pix[o+1u]=g;pix[o+2u]=r;}
static void line(int x0,int y0,int x1,int y1,re3c_u8 r,re3c_u8 g,re3c_u8 b){int dx=x1-x0,dy=y1-y0,sx=1,sy=1,err,e2;if(dx<0){dx=-dx;sx=-1;}if(dy<0){dy=-dy;sy=-1;}err=dx-dy;for(;;){dot(x0,y0,r,g,b);if(x0==x1&&y0==y1)break;e2=err*2;if(e2>-dy){err-=dy;x0+=sx;}if(e2<dx){err+=dx;y0+=sy;}}}
static int save_bmp(const char*path){FILE*f;re3c_u32 row=(re3c_u32)VW*3u,pad=(4u-(row&3u))&3u,img=(row+pad)*(re3c_u32)VH,size=54u+img,y;re3c_u8 z[3]={0,0,0};f=fopen(path,"wb");if(!f)return 0;fputc('B',f);fputc('M',f);put32(f,size);put32(f,0u);put32(f,54u);put32(f,40u);put32(f,VW);put32(f,VH);put16(f,1u);put16(f,24u);put32(f,0u);put32(f,img);put32(f,2835u);put32(f,2835u);put32(f,0u);put32(f,0u);for(y=0;y<(re3c_u32)VH;y++){re3c_u32 sy=(re3c_u32)VH-1u-y;fwrite(pix+(size_t)sy*row,1u,row,f);if(pad)fwrite(z,1u,pad,f);}fclose(f);return 1;}
static int project(re3c_i32 x,re3c_i32 y,re3c_i32 minx,re3c_i32 maxx,re3c_i32 miny,re3c_i32 maxy,int*ox,int*oy){re3c_i32 rx=maxx-minx,ry=maxy-miny,span,px,py;if(!ox||!oy)return 0;if(rx<=0)rx=1;if(ry<=0)ry=1;span=rx>ry?rx:ry;if(span<=0)span=1;px=(x-minx)*700/span;py=(y-miny)*700/span;*ox=50+(int)px;*oy=750-(int)py;return 1;}
int main(int argc,char**argv){re3c_model m;const re3c_mesh*mesh;re3c_i32 minx=0,maxx=0,miny=0,maxy=0;re3c_u32 i,j;int first=1,r;if(argc<3||argc>4){fprintf(stderr,"usage: %s file.EMD out.bmp [aux]\n",argv[0]);return 2;}re3c_model_init(&m);r=re3c_open_file(&m,argv[1]);if(r!=RE3C_OK){fprintf(stderr,"open: %s\n",re3c_result_string(r));return 1;}mesh=(argc==4&&strcmp(argv[3],"aux")==0)?&m.aux:&m.body;if(!mesh->part_count){fprintf(stderr,"mesh not present\n");re3c_model_close(&m);return 1;}for(i=0;i<mesh->vertex_count;i++){re3c_i32 x=re3c_fx_to_int(mesh->vertices[i].pos.x),y=-re3c_fx_to_int(mesh->vertices[i].pos.y);if(first){minx=maxx=x;miny=maxy=y;first=0;}else{if(x<minx)minx=x;if(x>maxx)maxx=x;if(y<miny)miny=y;if(y>maxy)maxy=y;}}clear_img();for(i=0;i<mesh->part_count;i++){const re3c_mesh_part*p=&mesh->parts[i];if(mesh==&m.body&&!re3c_part_should_render_default(p))continue;for(j=0;j<p->face_count;j++){const re3c_face*f=&mesh->faces[p->first_face+j];re3c_u32 k;for(k=0;k<f->vertex_count;k++){re3c_u32 a=f->vertex[k],b=f->vertex[(k+1u)%f->vertex_count];int x0,y0,x1,y1;re3c_i32 ax,ay,bx,by;if(a>=mesh->vertex_count||b>=mesh->vertex_count)continue;ax=re3c_fx_to_int(mesh->vertices[a].pos.x);ay=-re3c_fx_to_int(mesh->vertices[a].pos.y);bx=re3c_fx_to_int(mesh->vertices[b].pos.x);by=-re3c_fx_to_int(mesh->vertices[b].pos.y);project(ax,ay,minx,maxx,miny,maxy,&x0,&y0);project(bx,by,minx,maxx,miny,maxy,&x1,&y1);line(x0,y0,x1,y1,25u,25u,25u);}}}if(!save_bmp(argv[2])){fprintf(stderr,"cannot write %s\n",argv[2]);re3c_model_close(&m);return 1;}printf("wrote %s (%s mesh, %u parts)\n",argv[2],mesh==&m.aux?"aux":"body",(unsigned)mesh->part_count);re3c_model_close(&m);return 0;}
